const cfg  = $('Config').first().json;
const p    = $('Pipeline').first().json;
const m    = $('Money & Risk').first().json;
const comp = $('Compliance').first().json;
const lb   = ($('Leaderboard').first().json.agents) || [];
const worst = comp.worst || [];

const n = (v) => Number(v || 0).toLocaleString();
const bar = (label, value, max) => {
  const w = max > 0 ? Math.round((Number(value) / max) * 220) : 0;
  return `<tr><td style="padding:4px 10px 4px 0;white-space:nowrap;color:#374151">${label}</td>
  <td style="padding:4px 0"><span style="display:inline-block;height:14px;width:${w}px;background:#0f766e;border-radius:3px;vertical-align:middle"></span>
  <b style="margin-left:8px">${n(value)}</b></td></tr>`;
};
const funnel = [
  ['Leads - new', p.leads_new], ['Contacted', p.leads_contacted],
  ['Qualified', p.leads_qualified], ['Viewings booked', p.viewings_booked],
  ['Offers open', p.offers_open], ['Converted', p.leads_converted],
];
const max = Math.max(...funnel.map(f => Number(f[1] || 0)), 1);

const rows = worst.slice(0, 15).map(w =>
  `<tr><td style="padding:5px 10px 5px 0">${w.item}</td>
   <td style="padding:5px 10px 5px 0;color:#6b7280">${w.owner || '<i>nobody named</i>'}</td>
   <td style="padding:5px 10px 5px 0">${w.due}</td>
   <td style="padding:5px 0;font-weight:600;color:${Number(w.days) < 0 ? '#b91c1c' : '#b45309'}">
   ${Number(w.days) < 0 ? Math.abs(w.days) + 'd overdue' : 'in ' + w.days + 'd'}</td></tr>`).join('');

const agents = lb.slice(0, 10).map(a =>
  `<tr><td style="padding:5px 10px 5px 0">${a.agent}</td>
   <td style="padding:5px 10px 5px 0">${a.leads}</td>
   <td style="padding:5px 10px 5px 0;color:#047857">${a.converted}</td>
   <td style="padding:5px 0;color:#9ca3af">${a.lost}</td></tr>`).join('');

const html = `
<div style="font-family:system-ui,Segoe UI,sans-serif;max-width:720px;color:#111827">
<h2 style="margin:0 0 2px">DHARANI 360 - weekly pack</h2>
<div style="color:#6b7280;font-size:13px;margin-bottom:20px">
Week ending ${new Date().toISOString().slice(0,10)} &middot; computed from the registers, not typed by anyone</div>

<h3 style="margin:22px 0 8px;font-size:15px">Sales pipeline</h3>
<table style="border-collapse:collapse;font-size:14px">${funnel.map(f => bar(f[0], f[1], max)).join('')}</table>
<p style="font-size:13px;color:#374151">
${n(p.leads_this_week)} new leads this week &middot; ${n(p.deals_closed_7d)} deals closed &middot;
<b style="color:${Number(p.leads_unassigned) > 0 ? '#b91c1c' : '#047857'}">${n(p.leads_unassigned)} unassigned</b></p>

<h3 style="margin:22px 0 8px;font-size:15px">Compliance</h3>
<p style="font-size:14px">
<b style="color:#b91c1c">${n(comp.overdue)} overdue</b> &middot;
<b style="color:#b45309">${n(comp.red)} due inside 30 days</b> &middot;
${n(comp.amber)} due in 31-90 days</p>
${rows ? `<table style="border-collapse:collapse;font-size:13px">
<tr style="text-align:left;color:#6b7280"><th>Item</th><th>Owner</th><th>Expires</th><th></th></tr>${rows}</table>` : '<p style="font-size:13px;color:#047857">Nothing red. Genuinely.</p>'}

<h3 style="margin:22px 0 8px;font-size:15px">Money waiting on somebody</h3>
<p style="font-size:14px">
${n(m.commissions_awaiting)} commissions awaiting approval (AED ${n(m.commissions_value)}) &middot;
${n(m.claims_pending)} expense claims &middot; ${n(m.payments_pending)} payments</p>

<h3 style="margin:22px 0 8px;font-size:15px">Risk</h3>
<p style="font-size:14px">
${n(m.aml_high_risk)} clients rated High Risk &middot;
${n(m.compliance_open)} open compliance incidents &middot;
${n(m.security_open)} open security incidents</p>

<h3 style="margin:22px 0 8px;font-size:15px">Agents - last 30 days</h3>
${agents ? `<table style="border-collapse:collapse;font-size:13px">
<tr style="text-align:left;color:#6b7280"><th>Agent</th><th>Leads</th><th>Converted</th><th>Lost</th></tr>${agents}</table>` : '<p style="font-size:13px;color:#6b7280">No leads in the last 30 days.</p>'}

<p style="margin-top:26px;font-size:12px;color:#9ca3af">
Open the Control Tower: <a href="${cfg.portal_url}">${cfg.portal_url}</a></p>
</div>`;

const plain = `Weekly pack: ${n(p.leads_this_week)} new leads, ${n(p.deals_closed_7d)} closed, `
  + `${n(comp.overdue)} overdue and ${n(comp.red)} red compliance items, `
  + `${n(m.commissions_awaiting)} commissions awaiting approval.`;

return String(cfg.recipients).split(',').map(to => ({ json: {
  channel: 'email', to_email: to.trim(),
  subject: `[DHARANI 360] Weekly pack - ${n(comp.overdue)} overdue, ${n(p.leads_unassigned)} leads unassigned`,
  message: plain, html,
}}));
